396	+// LocalEvent — scriptable single-click driver.
397	+//
398	+// A test that wants to exercise a real, integrated right-click (rather than calling
399	+// ScenarioListBox::ActionListPressRight directly on a bare, unconfigured instance) sets
400	+// g_fakeMouseX/Y and g_fakeRightPressed, sets g_fakeEventsRemaining = 1, then calls the
401	+// real Dialog::SelectScenario(). HandleEvents() reports the fake cursor position and lets
402	+// the loop body run for exactly that many iterations. This is what makes it fair to ANY
403	+// correct fix: the real setup code runs (whatever geometry/state it wires up), and the
404	+// real dispatch chain (QueueEventProcessing -> ActionListPressRight, and the main loop's
405	+// own right-click checks) decides the outcome -- nothing here is specific to one
406	+// implementation's internal structure.
407	+//
408	+// IMPORTANT: the real Dialog::Message / fheroes2::showMessage, when called with no
409	+// buttons (as every popup in this dialog is), run their own loop that blocks until the
410	+// right mouse button is RELEASED -- see dialog_message.cpp / ui_dialog.cpp upstream:
411	+// `while (... ) { if (!buttons && !le.MousePressRight()) break; ... }`. So by the time any
412	+// such popup returns, a right-click has necessarily been consumed: a later check in the
413	+// same frame (e.g. a second, redundant right-click test further down the dispatch chain)
414	+// will correctly see the button as no longer pressed. The Dialog::Message/showMessage
415	+// stubs below clear g_fakeRightPressed for exactly this reason -- without it, a fix that
416	+// relies on this real ordering (show the correct popup first, then let a later redundant
417	+// check no-op because the click is already consumed) would be unfairly rejected here.
418	+// -----------------------------------------------------------------------
419	+LocalEvent::LocalEvent() {}
420	+LocalEvent & LocalEvent::Get() { static LocalEvent le; return le; }
421	+
422	+bool LocalEvent::HandleEvents(bool, bool)
423	+{
424	+    mouse_cu = fheroes2::Point(g_fakeMouseX, g_fakeMouseY);
425	+    if (g_fakeEventsRemaining > 0) {
426	+        --g_fakeEventsRemaining;
427	+        return true;
428	+    }
429	+    return false;
430	+}
