560	+// BEHAVIORAL, integration-level: drives the real Dialog::SelectScenario() through exactly
561	+// one frame with a simulated right-click over an icon column, using the same call path
562	+// (QueueEventProcessing -> ActionListPressRight, plus the dialog's own right-click
563	+// dispatch) the real game uses. Deliberately NOT a bare, isolated ScenarioListBox: a
564	+// correct fix may need per-column geometry that only Dialog::SelectScenario's own setup
565	+// provides (e.g. state populated on the listbox before its event loop starts), and calling
566	+// ActionListPressRight directly on an unconfigured instance would then unfairly reject
567	+// that (perfectly valid) design.
568	+TEST(ScenarioListBox, IconAreaRightClickDoesNotShowPopup)
569	+{
570	+    g_showMessageCallCount = 0;
571	+
572	+    MapsFileInfoList maps;
573	+    maps.push_back( makeStandardMap( "TestMap" ) );
574	+
575	+    // Display is 640x480 and the panel background sprite is 0x0 in this harness, so
576	+    // Dialog::SelectScenario's panel rect (rt) is deterministically (320, 240) here. The
577	+    // size-icon column sits at rt.x+64 .. rt.x+83 per the dialog's own layout; aim for its
578	+    // center, comfortably clear of the columns on either side.
579	+    g_fakeMouseX = 390;
580	+    g_fakeMouseY = 300;
581	+    g_fakeRightPressed = true;
582	+    g_fakeEventsRemaining = 1;
583	+
584	+    Dialog::SelectScenario( maps, 0 );
585	+
586	+    EXPECT_EQ(g_showMessageCallCount, 0)
587	+        << "Right-clicking in the icon area triggered fheroes2::showMessage "
588	+        << g_showMessageCallCount << " time(s). It must not show the map-info popup.";
589	+}
