592	+// details panel below the list -- and checks where it draws the "Map difficulty:" label
593	+// relative to the panel's own origin. The label is always the second text draw once a map
594	+// is selected (map name, then difficulty label, then difficulty value), regardless of how
595	+// the fix is implemented internally.
596	+TEST(ScenarioListBox, DifficultyLabelAlignsWithPanelEdge)
597	+{
598	+    ScenarioListBox listbox( fheroes2::Point( 0, 0 ) );
599	+    listbox.SetAreaMaxItems( 1 );
600	+
601	+    MapsFileInfoList maps;
602	+    maps.push_back( makeStandardMap( "TestMap" ) );
603	+    listbox.SetListContent( maps );
604	+    listbox.SetCurrent( 0 );
605	+
606	+    for ( const int32_t dstx : { 100, 250 } ) {
607	+        g_textBlitCalls.clear();
608	+        listbox.RedrawBackground( fheroes2::Point( dstx, 50 ) );
609	+
610	+        ASSERT_GE( g_textBlitCalls.size(), 2u )
611	+            << "Expected at least the map-name and difficulty-label draws once a map is selected (dst.x=" << dstx << ").";
612	+
613	+        const int32_t expectedX = dstx + 210;
614	+        EXPECT_EQ( g_textBlitCalls[1].first, expectedX )
615	+            << "The \"Map difficulty:\" label is not aligned with the panel edge (dst.x=" << dstx << ").";
616	+    }
617	+}
