al_victory(false)\n+    , wins1(0), wins2(0)\n+    , conditions_loss(0), loss1(0), loss2(0)\n+    , localtime(0), startWithHeroInEachCastle(false)\n+{\n+    for (int i = 0; i < KINGDOMMAX; ++i) { races[i] = 0; unions[i] = 0; }\n+}\n+\n+Maps::FileInfo::FileInfo(const FileInfo & f) { *this = f; }\n+\n+Maps::FileInfo & Maps::FileInfo::operator=(const Maps::FileInfo & f)\n+{\n+    file = f.file; name = f.name; description = f.description;\n+    size_w = f.size_w; size_h = f.size_h; difficulty = f.difficulty;\n+    for (int i = 0; i < KINGDOMMAX; ++i) { races[i] = f.races[i]; unions[i] = f.unions[i]; }\n+    kingdom_colors = f.kingdom_colors; allow_human_colors = f.allow_human_colors;\n+    allow_comp_colors = f.allow_comp_colors; rnd_races = f.rnd_races;\n+    conditions_wins = f.conditions_wins; comp_also_wins = f.comp_also_wins;\n+    allow_normal_victory = f.allow_normal_victory; wins1 = f.wins1; wins2 = f.wins2;\n+    conditions_loss = f.conditions_loss; loss1 = f.loss1; loss2 = f.loss2;\n+    localtime = f.localtime; startWithHeroInEachCastle = f.startWithHeroInEachCastle;\n+    _version = f._version;\n+    return *this;\n+}\n+\n+// -----------------------------------------------------------------------\n+// Translation\n+// -----------------------------------------------------------------------\n+const char * Translation::gettext(const char * s) { return s; }\n+const char * Translation::gettext(const std::string & s) { return s.c_str(); }\n+const char * Translation::ngettext(const char * s, const char *, size_t) { return s; }\n+\n+// -----------------------------------------------------------------------\n+// StringReplace (from tools.h)\n+// -----------------------------------------------------------------------\n+void StringReplace(std::string & str, const char * from, const std::string & to)\n+{\n+    size_t pos = 0;\n+    while ((pos = str.find(from, pos)) != std::string::npos) {\n+        str.replace(pos, strlen(from), to);\n+        pos += to.length();\n+   